/* Writing images, AI, name matching */
async function showWritingPhotos(){const p=active(),part=photoScreen===2?6:7;if(!p)return;const w=rec(p.id).writing[part],area=$('#writing-photos');if(!area)return;let blocks=[];for(let i=0;i<w.images.length;i++){const data=await kvGet(w.images[i]);blocks.push(`<div class="photo-thumb"><img alt="Writing page ${i+1}" src="${E(data||'')}"><button type="button" data-remove-writing="${part}" data-photo-index="${i}" title="Remove photograph">×</button></div>`)}area.innerHTML=blocks.join('')}
async function callAI(path,payload){if(!state.settings.backend)throw Error('Configure the secure AI backend in Settings first.');if(!token)throw Error('Enter your teacher access token in Settings first.');const url=state.settings.backend.replace(/\/$/,'')+'/'+path;const ctl=new AbortController(),timeout=setTimeout(()=>ctl.abort(),path==='extract-exam'?150000:80000);let response;try{response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-Teacher-Token':token},body:JSON.stringify(payload),signal:ctl.signal})}finally{clearTimeout(timeout)}let reply=await response.json().catch(()=>({error:'Invalid response from AI backend'}));if(!response.ok)throw Error(reply.error||`AI request failed (${response.status})`);return reply}
