function openMark(id,step=null){if(!classInfo()?.pupils.some(p=>p.id===id))return;activePupil=id;if(step===null){const r=rec(id);if(r.scores.slice(0,4).some(v=>v===null))step=0;else if(r.scores[4]===null)step=1;else if(r.scores[5]===null)step=2;else if(r.scores[6]===null)step=3;else step=4}photoScreen=step;omrCache=null;omrOverlayImage=null;omrMode='auto';alignMode=false;go('mark')}
async function savePupil(advance=false){const p=active();if(!p)return;const r=rec(p.id);r.updated=new Date().toISOString().slice(0,19).replace('T',' ');await save();if(state.settings.autoSync&&googleToken&&totals(p)!==null)syncSheets().catch(e=>toast('Saved locally, but Sheets sync failed: '+e.message));if(advance){const cls=classInfo(),pos=cls.pupils.findIndex(x=>x.id===p.id),others=[...cls.pupils.slice(pos+1),...cls.pupils.slice(0,pos)].filter(p=>attendance()[p.id]!==false&&markStatus(p)!=='completed');if(others.length){toast('Result saved. Next pupil loaded.');openMark(others[0].id)}else{toast('Saved. No remaining pupils in this class.');go('roster')}}else{toast('Result saved locally.');go('roster')}}
/* Google Sheets: optional browser OAuth. No teacher or cloud keys in static HTML. */
async function loadGIS(){if(window.google?.accounts?.oauth2)return;await new Promise((yes,no)=>{const s=document.createElement('script');s.src='https://accounts.google.com/gsi/client';s.onload=yes;s.onerror=()=>no(Error('Could not load Google sign-in (internet required)'));document.head.append(s)})}
async function connectGoogle(){const cid=state.settings.oauthClient;if(!cid||!state.settings.sheetId)throw Error('Enter the Google OAuth client ID and spreadsheet ID first.');await loadGIS();await new Promise((resolve,reject)=>{const client=google.accounts.oauth2.initTokenClient({client_id:cid,scope:'https://www.googleapis.com/auth/spreadsheets',callback:(r)=>{if(r.error){reject(Error(r.error));return}googleToken=r.access_token;resolve()}});client.requestAccessToken({prompt:'consent'})});render();toast('Connected to Google Sheets. You can now sync results.')}
async function googleReq(url,method='GET',body=null){if(!googleToken)throw Error('Connect your Google account first in Settings');const r=await fetch('https://sheets.googleapis.com/v4/spreadsheets/'+url,{method,headers:{Authorization:'Bearer '+googleToken,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error?.message||`Google Sheets error ${r.status}`);return j}
