async function backupAll(){const db=await dbPromise,items=await new Promise((res,rej)=>{const store=db.transaction('kv','readonly').objectStore('kv'),req=store.getAllKeys();req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)}),records={};for(const key of items){const v=await kvGet(key);if(v instanceof Uint8Array){let s='';for(let i=0;i<v.length;i+=16384)s+=String.fromCharCode(...v.subarray(i,i+16384));records[key]={binary:btoa(s)}}else records[key]=v}downloadFile(new Blob([JSON.stringify({paperMarkBackupVersion:1,created:new Date().toISOString(),records})],{type:'application/json'}),'PaperMark_PRIVATE_Backup.json');toast('Private full backup downloaded; store it securely.')}
async function restoreAll(file){const data=JSON.parse(await file.text());if(data.paperMarkBackupVersion!==1||!data.records)throw Error('Not a valid PaperMark backup');if(!confirm('Restore backup? Existing local marking records will be replaced.'))return;for(const [k,v] of Object.entries(data.records)){if(v&&typeof v==='object'&&'binary'in v){const s=atob(v.binary),arr=new Uint8Array(s.length);for(let i=0;i<s.length;i++)arr[i]=s.charCodeAt(i);await kvPut(k,arr)}else await kvPut(k,v)}state=await kvGet('state')||stateDefault();workbookEntries=null;schemeCache=null;omrCache=null;go('home');toast('Backup restored.')}
function drawSchemeAnswers(){const box=$('#scheme-keys');if(!box)return;const key=exam().keyAnswers||[],flags=exam().keyFlags||[];box.innerHTML=`<h3>Confirm the 20 answers</h3><p class="subtitle">Tap the correct letter if any detected answer is wrong. This overrides the scanner's key reading.</p><div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(145px,1fr));gap:8px">${Array.from({length:20},(_,i)=>`<div class="row" style="border:1px solid #e2eae6;border-radius:9px;padding:6px"><b style="font-size:12px">${i+1}${flags[i]?' ⚠':''}</b><div class="seg">${['A','B','C'].map(c=>`<button class="${key[i]===c?'on':''}" style="padding:6px 8px" data-key-answer="${i}" data-choice="${c}">${c}</button>`).join('')}</div></div>`).join('')}</div>`}
let fileCallback=null;
function pickFile(accept,cb,capture=false){const f=$('#hidden-file');f.value='';f.accept=accept;f.multiple=false;if(capture)f.setAttribute('capture','environment');else f.removeAttribute('capture');fileCallback=cb;f.click()}
async function cameraFor(cb){if(!navigator.mediaDevices?.getUserMedia){pickFile('image/*',cb,true);return}let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:2000},height:{ideal:2700}}})}catch(e){pickFile('image/*',cb,true);return}const m=document.createElement('div');m.className='cam-modal';m.innerHTML=`<div class="cam-card"><div class="row"><b>Camera</b>${btn('Close','','id="close-camera"')}</div><video autoplay playsinline muted></video><div class="actions end">${btn('Capture photo','primary','id="take-photo"')}</div></div>`;document.body.append(m);const v=$('video',m);v.srcObject=stream;const close=()=>{stream.getTracks().forEach(t=>t.stop());m.remove()};$('#close-camera',m).onclick=close;$('#take-photo',m).onclick=async()=>{if(!v.videoWidth)return toast('Camera not ready.');const c=document.createElement('canvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);const blob=await new Promise(ok=>c.toBlob(ok,'image/jpeg',.94));close();await cb(new File([blob],'camera.jpg',{type:'image/jpeg'}))}}
async function processOMRPhoto(file){const p=active();if(!p)return;const data=await resizePhoto(file),key=`image:omr:${xKey()}:${p.id}`;await kvPut(key,data);const r=rec(p.id);r.omrImage=key;r.corners=null;r.omrMarks=null;r.omrAnswers=null;r.omrFlags=null;r.omrScanned=false;r.scores.splice(0,4,null,null,null,null);omrCache=null;omrOverlayImage=null;await save();render();const img=await getPupilImg();r.corners=proposeCorners(img);await save();if(exam().scheme&&omrMode==='auto'){try{await scanPupil();render()}catch(err){toast('Auto scan needs review: '+err.message)}}toast('Pupil answer sheet saved')}
async function addWritingPhoto(file,part){const p=active(),data=await resizePhoto(file),w=rec(p.id).writing[part];const key=`image:writing:${xKey()}:${p.id}:${part}:${Date.now()}_${Math.round(Math.random()*9999)}`;await kvPut(key,data);w.images.push(key);w.details=null;w.approved=false;w.score=null;rec(p.id).scores[part-1]=null;await save();render();toast(`Part ${part} photo added`)}

/* Whole-paper setup. The source file is stored separately in IndexedDB; pupil records remain unchanged. */
function paperMime(file){const type=(file.type||'').toLowerCase();if(/\.pdf$/i.test(file.name))return'application/pdf';if(/\.docx$/i.test(file.name))return'application/vnd.openxmlformats-officedocument.wordprocessingml.document';if(/\.(jpg|jpeg|png|webp)$/i.test(file.name))return type||(/\.png$/i.test(file.name)?'image/png':/\.webp$/i.test(file.name)?'image/webp':'image/jpeg');throw Error('Upload a PDF, Word .docx or JPG/PNG/WebP examination paper.')} 
async function bytesToDataURL(bytes,mime){const blob=new Blob([bytes],{type:mime});return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
function mediaType(name){if(/\.png$/i.test(name))return'image/png';if(/\.webp$/i.test(name))return'image/webp';if(/\.jpe?g$/i.test(name))return'image/jpeg';return null}
async function wordContent(bytes){const zip=await readZip(bytes),doc=zip.get('word/document.xml');if(!doc)throw Error('This Word document contains no readable document.xml');const root=xml(td.decode(doc));const paragraphs=xnodes(root,'p').map(p=>xnodes(p,'t').map(t=>t.textContent).join('').trim()).filter(Boolean);const images=[];for(const [path,b] of zip){if(!path.startsWith('word/media/'))continue;const mime=mediaType(path);if(!mime||b.length>1800000)continue;images.push(await bytesToDataURL(b,mime));if(images.length>=7)break}return{text:paragraphs.join('\n').slice(0,40000),images}}
function detectPart(text,part){const esc=String(text||'');const lines=esc.split(/\r?\n/);const re=new RegExp('(?:^|\\b)(?:part|bahagian)\\s*'+part+'\\b','i');let idx=lines.findIndex(x=>re.test(x));if(idx<0)return'';const next=new RegExp('(?:^|\\b)(?:part|bahagian)\\s*'+(part+1)+'\\b','i');let output=[];for(let i=idx;i<lines.length&&output.join(' ').length<6000;i++){if(i>idx&&next.test(lines[i]))break;output.push(lines[i])}return output.join('\n').trim()}
async function saveExamPaper(file){const mime=paperMime(file);if(file.size>12500000)throw Error('Exam paper is over 12.5 MB. Compress it or upload a smaller PDF.');const bytes=new Uint8Array(await file.arrayBuffer()),k='document:exam:'+sKey(),e=exam();await kvPut(k,bytes);e.paper={name:file.name,type:mime,size:file.size,key:k,added:new Date().toISOString()};e.paperReviewed=false;e.extractNotes='';if(mime.includes('wordprocessingml')){try{const parsed=await wordContent(bytes);e.wordText=parsed.text;for(const part of [6,7]){const found=detectPart(parsed.text,part);if(found)e.prompts[part]=found}e.extractNotes='Word text was read locally. Check Part 6 and 7 carefully: embedded picture cues may require AI extraction.'}catch(err){e.extractNotes='Could not parse Word text automatically: '+err.message}}else e.wordText='';await save();render();toast('Exam paper saved. Review tasks and approve before marking.');}
async function downloadExamPaper(){const e=exam();if(!e.paper)throw Error('No paper uploaded');const bytes=await kvGet(e.paper.key);if(!bytes)throw Error('Saved paper not found on this device');downloadFile(new Blob([bytes],{type:e.paper.type}),e.paper.name)}
async function extractExamPaper(){const e=exam();if(!e.paper)throw Error('Upload the complete exam first');if(!state.settings.backend||!token)throw Error('Configure the secure AI connection in Settings to extract the exam automatically. Otherwise, enter and approve the Part 6 and 7 tasks here once.');const bytes=await kvGet(e.paper.key);if(!bytes)throw Error('Saved exam file is missing');let payload={year:classInfo().year,set:state.activeSet,name:e.paper.name};if(e.paper.type==='application/pdf'){payload.pdf=await bytesToDataURL(bytes,'application/pdf')}else if(e.paper.type.includes('wordprocessingml')){const parsed=await wordContent(bytes);payload.text=parsed.text;payload.images=parsed.images}else{payload.images=[await bytesToDataURL(bytes,e.paper.type)]}const status=$('#exam-extract-status');if(status)status.textContent='Extracting questions and picture cues…';try{const result=await callAI('extract-exam',payload);if(typeof result.part6==='string'&&result.part6.trim())e.prompts[6]=result.part6.trim();if(typeof result.part7==='string'&&result.part7.trim())e.prompts[7]=result.part7.trim();if(Array.isArray(result.part5)&&result.part5.length===5)e.labels=result.part5.map((x,i)=>String(x||'').trim()||e.labels[i]||'').slice(0,5);e.extractNotes=String(result.uncertainty||'').slice(0,1200);e.paperReviewed=false;await save();render();toast('Questions extracted. Check and approve the tasks before grading.')}catch(err){if(status)status.textContent='Extraction failed: '+err.message;throw err}}
async function approveExamSetup(){const e=exam();for(const part of [6,7])e.prompts[part]=$(`.exam-task[data-part="${part}"]`)?.value.trim()||'';for(let i=0;i<5;i++)e.labels[i]=$(`.part5-label[data-n="${i}"]`)?.value.trim()||'';if(!e.prompts[6]||!e.prompts[7])throw Error('Fill in both Part 6 and Part 7 tasks before approving.');e.paperReviewed=true;await save();render();toast('Exam questions confirmed. They will be reused for all pupils in this Year / Set.');}

function savePartPrompt(part){const field=$('#writing-prompt');if(field){exam().prompts[part]=field.value;save()}}
function setCompletedOMR(){const r=rec(activePupil);if(!r.omrMarks||r.omrMarks.length!==20)throw Error('Scan or mark the OMR answers first.');const scores=PART_RANGES.map(([lo,hi])=>r.omrMarks.slice(lo-1,hi).filter(Boolean).length);for(let i=0;i<4;i++)r.scores[i]=scores[i];r.updated=new Date().toISOString().slice(0,19).replace('T',' ');save()}
async function updateMarkingChoice(el){if(el.hasAttribute('data-p5')){const idx=+el.dataset.p5,val=el.dataset.value==='yes',r=rec(activePupil);r.p5[idx]=val;await save();render();return}
if(el.hasAttribute('data-approve')){const part=+el.dataset.approve,n=$('.writing-score');const value=Number(n?.value),max=MAX[part-1];if(n?.value.trim()===''||!Number.isInteger(value)||value<0||value>max)throw Error(`Enter a whole-number mark between 0 and ${max}.`);const r=rec(activePupil),w=r.writing[part];w.score=value;w.approved=true;r.scores[part-1]=value;await save();render();toast(`Part ${part} score approved: ${value}/${max}`);return}
if(el.hasAttribute('data-unapprove')){const part=+el.dataset.unapprove,r=rec(activePupil),w=r.writing[part];w.approved=false;r.scores[part-1]=null;await save();render();return}}
function goNextMark(part){if(part===5){const r=rec(activePupil);if(r.p5.some(v=>v===null))throw Error('Please choose ✓ or ✕ for all five questions.');r.scores[4]=r.p5.filter(Boolean).length;save();photoScreen=2;render();return}if(part===6||part===7){savePartPrompt(part);photoScreen=part===6?3:4;render()}}
/* Central event handler: touch and mouse both use pointer/click events */
async function onAction(e){const el=e.target.closest('button');if(!el)return;try{
if(el.matches('[data-go]')){go(el.dataset.go);return}
if(el.matches('[data-page]')){go(el.dataset.page);if(window.innerWidth<900)$('#aside').style.display='none';return}
if(el.id==='mobile-menu'){const side=$('#aside');side.style.display=side.style.display==='block'?'none':'block';side.style.position='fixed';side.style.top='47px';side.style.left=0;side.style.height='auto';side.style.zIndex=80;side.style.width='240px';return}
if(el.matches('[data-mark]')){if(attendance()[el.dataset.mark]===false)throw Error('This pupil is marked absent. Check Present in Attendance before marking.');openMark(el.dataset.mark);return}
if(el.matches('[data-step]')){if(photoScreen===2||photoScreen===3)savePartPrompt(photoScreen===2?6:7);photoScreen=+el.dataset.step;render();return}
if(el.id==='import-book'){pickFile('.xlsx',async f=>{const x=await importWorkbook(f);go('home');toast(`Imported ${x.total} pupils in ${x.groups} classes`)});return}
if(el.id==='start-mark'){if(!exam().paper&&!Object.keys(records()).some(k=>(records()[k].scores||[]).some(v=>v!==null))){go('scheme');toast('Upload the complete exam paper and confirm Part 6–7 tasks before marking.');return}const p=classInfo().pupils.find(p=>attendance()[p.id]!==false&&markStatus(p)!=='completed')||classInfo().pupils.find(p=>attendance()[p.id]!==false);if(!p)throw Error('No present pupils in this class.');openMark(p.id);return}
if(el.id==='all-present'||el.id==='all-absent'){const at=attendance();for(let p of classInfo().pupils)at[p.id]=el.id==='all-present';await save();render();return}
if(el.id==='upload-exam-paper'){pickFile('.pdf,.docx,image/jpeg,image/png,image/webp',saveExamPaper);return}
if(el.id==='download-exam-paper'){await downloadExamPaper();return}
if(el.id==='extract-exam-paper'){el.disabled=true;const label=el.textContent;el.textContent='Extracting paper…';try{await extractExamPaper()}finally{el.disabled=false;el.textContent=label}return}
if(el.id==='approve-exam-setup'){await approveExamSetup();return}
if(el.id==='scheme-upload'){pickFile('image/*',async f=>{const id=`image:scheme:${sKey()}`,before=exam().scheme;await kvPut(id,await resizePhoto(f));exam().scheme=id;exam().anchors=null;exam().keyOverrides={};schemeCache=null;await scanScheme();if(before)invalidateSchemeMarks();await save();render();toast('Answer scheme saved and bubbles detected')});return}
if(el.id==='toggle-calib'){schemeCalMode=!schemeCalMode;el.textContent=schemeCalMode?'Finish adjusting':'Adjust 8 anchor points';displayScheme();return}
if(el.id==='reset-anchors'){exam().anchors=null;await scanScheme();invalidateSchemeMarks();await save();render();toast('Default anchors restored — previous OMR marks require rescanning');return}
if(el.id==='check-scheme'){await scanScheme();drawSchemeAnswers();toast('Review detected answers and correct any incorrect letters');return}
if(el.matches('[data-key-answer]')){const i=+el.dataset.keyAnswer,ch=el.dataset.choice,ex=exam();ex.keyOverrides??={};ex.keyOverrides[i]=ch;ex.keyAnswers[i]=ch;invalidateSchemeMarks();await save();drawSchemeAnswers();toast('Key updated; existing OMR marks must be rescanned.');return}
if(el.id==='save-labels'){for(let i=0;i<5;i++)exam().labels[i]=$(`.part5-label[data-n="${i}"]`)?.value.trim()||'';await save();toast('Part 5 labels saved');return}
if(el.id==='capture-omr'){await cameraFor(processOMRPhoto);return}
if(el.id==='upload-omr'){pickFile('image/*',processOMRPhoto);return}
if(el.matches('[data-mode]')){omrMode=el.dataset.mode;render();return}
if(el.id==='toggle-zoom'||el.id==='omr-close-zoom'){$('#omr-frame')?.classList.toggle('zoomed',el.id==='toggle-zoom');return}
if(el.id==='toggle-align'){alignMode=!alignMode;cornerDrag=-1;if(!alignMode)omrCache=null;render();return}
if(el.id==='auto-align'){const img=await getPupilImg();rec(activePupil).corners=proposeCorners(img);omrCache=null;await save();displayOMR();toast('Automatic page-corner estimate applied');return}
if(el.id==='scan-auto'){await scanPupil();omrMode='auto';render();toast('Auto scan complete. Check uncertain answers before continuing.');return}
if(el.id==='finish-omr'){setCompletedOMR();photoScreen=1;render();return}
if(el.id==='read-name'){await ocrName();return}
if(el.matches('[data-ocr-select]')){const id=el.dataset.ocrSelect;if(id!==activePupil){if(!confirm('Use this pupil name for the scanned paper? The photo will move to their record.'))return;const from=rec(activePupil),to=rec(id);to.omrImage=from.omrImage;to.corners=from.corners;to.omrMarks=from.omrMarks;to.omrAnswers=from.omrAnswers;to.omrFlags=from.omrFlags;to.omrScanned=from.omrScanned;to.scores.splice(0,4,...from.scores.slice(0,4));from.omrImage=null;from.corners=null;from.omrMarks=null;from.omrAnswers=null;from.omrScanned=false;from.scores.splice(0,4,null,null,null,null);activePupil=id;omrCache=null;omrOverlayImage=null;await save();render()}return}
if(el.id==='finish-p5'){goNextMark(5);return}
if(el.id==='batch-next'){const r=rec(activePupil);if(r.p5.some(v=>v===null))throw Error('Mark all five Part 5 questions before proceeding.');r.scores[4]=r.p5.filter(Boolean).length;await savePupil(true);return}
if(el.hasAttribute('data-p5')||el.hasAttribute('data-approve')||el.hasAttribute('data-unapprove')){await updateMarkingChoice(el);return}
if(el.matches('[data-camera-writing]')){const part=+el.dataset.cameraWriting;await cameraFor(f=>addWritingPhoto(f,part));return}
if(el.matches('[data-upload-writing]')){const part=+el.dataset.uploadWriting;pickFile('image/*',f=>addWritingPhoto(f,part));return}
if(el.matches('[data-remove-writing]')){const part=+el.dataset.removeWriting,i=+el.dataset.photoIndex;if(!confirm('Remove this writing photograph?'))return;const w=rec(activePupil).writing[part],key=w.images.splice(i,1)[0];await kvDelete(key);w.score=null;w.details=null;w.approved=false;rec(activePupil).scores[part-1]=null;await save();render();return}
if(el.id==='save-writing-prompt'){savePartPrompt(photoScreen===2?6:7);toast('Question saved for this examination set');return}
if(el.matches('[data-grade]')){savePartPrompt(+el.dataset.grade);el.disabled=true;el.textContent='AI assessing…';await gradeWriting(+el.dataset.grade);return}
if(el.matches('[data-manual-writing]')){const f=$('.writing-score');f?.focus();toast('Enter your own mark and press Approve & save score.');return}
if(el.matches('[data-writing-next]')){goNextMark(+el.dataset.writingNext);return}
if(el.id==='save-next'){await savePupil(true);return}
if(el.id==='save-roster'){await savePupil(false);return}
if(el.id==='export-xlsx'){await exportWorkbook();return}
if(el.id==='save-backend'){state.settings.backend=$('#backend-url').value.trim();token=$('#teacher-token').value.trim();sessionStorage.setItem('papermark-token',token);await save();toast('AI connection saved (teacher token held for this browser session)');return}
if(el.id==='save-google'){state.settings.oauthClient=$('#google-client').value.trim();state.settings.sheetId=$('#sheet-id').value.trim();state.settings.autoSync=$('#auto-sync').checked;await save();toast('Google Sheets settings saved');return}
if(el.id==='connect-google'){await connectGoogle();return}
if(el.id==='sync-google'){await syncSheets();return}
if(el.id==='backup-json'){await backupAll();return}
if(el.id==='restore-json'){pickFile('.json',restoreAll);return}
}catch(err){console.error(err);toast(err.message||'Unexpected error','error')}}
function bindPage(){const cs=$('#class-select'),ss=$('#set-select');if(cs)cs.addEventListener('change',async e=>{state.activeClass=e.target.value;await save();render()});if(ss)ss.addEventListener('change',async e=>{state.activeSet=+e.target.value;await save();render()});$$('.present-check').forEach(el=>el.addEventListener('change',async e=>{attendance()[e.target.dataset.id]=e.target.checked;await save();render()}));$('#roster-filter')?.addEventListener('input',e=>{$$('#roster-tbody tr').forEach(tr=>tr.classList.toggle('hide',!tr.dataset.name.includes(U(e.target.value))))});$('#overlay-opacity')?.addEventListener('input',e=>{overlayAlpha=+e.target.value/100;$('#opacity-num').textContent=e.target.value+'%';displayOMR()});if(page==='scheme'){displayScheme();if((exam().keyAnswers||[]).length)drawSchemeAnswers()}if(page==='mark'&&photoScreen===0)displayOMR();if(page==='mark'&&(photoScreen===2||photoScreen===3))showWritingPhotos()}
document.addEventListener('click',onAction);
$('#hidden-file').addEventListener('change',async e=>{const cb=fileCallback,file=e.target.files?.[0];fileCallback=null;if(!file||!cb)return;try{await cb(file)}catch(err){console.error(err);toast(err.message||'Could not load file','error')}});
async function boot(){try{state=await kvGet('state')||stateDefault();const b=await kvGet('workbook');if(b)try{workbookEntries=await readZip(b)}catch(e){console.warn('Saved workbook not accessible',e)}if(!state.classes)state=stateDefault();if(!state.activeClass||!state.classes[state.activeClass])state.activeClass=Object.keys(state.classes)[0]||'';render();if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js').catch(console.warn)}catch(e){console.error('Startup error',e);$('#app').innerHTML=notice('Could not initialise local storage. Use a normal (non-private) browser window and refresh.','error')}}
boot();
